fn asq8_reference_envelope(
    profile: [u8; 32], release: [u8; 32], program: [u8; 32], kind: u8,
    payment: [u8; POOL_V1_PAYMENT_STATEMENT_BYTES],
) -> [u8; POOL_V1_PAIR_FOREST_TERMINAL_REQUEST_BYTES] {
